+
+  /// Path of the diagnostic log file under `~/.fah/logs/fa.log`. Null
+  /// when the host has no `homeDir` (web build, sandbox).
+  String? get _diagnosticLogPath {
+    final home = config.homeDir;
+    if (home == null || home.isEmpty) return null;
