import 'package:fa/services/media_models_store.dart';
import 'package:fa/services/provider_registry.dart';
import 'package:fa/ui/screens/media_slot_picker_page.dart';
import 'package:fa/ui/screens/provider_editor_page.dart';
import 'package:fa_ui/fa_ui.dart' show FaVoicePresetPicker;
import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:fa_ui/fa_ui.dart' show AddProviderPresetPickerPage, FaUiHost;

/// A `/models` fetch reporting image and vision models.
Future<ModelsEndpointInfo> _someModels(
  String baseUrl, {
  required String apiKey,
}) async => (
  const ['gpt-image-1', 'dall-e-3', 'gpt-4o'],
  const <String, int>{},
  const <String, int>{},
);

/// Pumps a home button that pushes [page] and captures its pop result.
Future<void> _pumpWithOpener(
  WidgetTester tester,
  Widget page,
  void Function(MediaSlotEditorResult?) onResult,
) {
  return tester.pumpWidget(
    MaterialApp(
      home: Builder(
        builder: (context) => Scaffold(
          body: FilledButton(
            onPressed: () async {
              final result = await Navigator.of(context)
                  .push<MediaSlotEditorResult>(
                    MaterialPageRoute(builder: (_) => page),
                  );
              onResult(result);
            },
            child: const Text('open'),
          ),
        ),
      ),
    ),
  );
}

Future<void> _open(WidgetTester tester) async {
  await tester.tap(find.text('open'));
  await tester.pumpAndSettle();
}

void main() {
  group('MediaSlotProviderPickerPage', () {
    testWidgets('renders the main connection, presets, custom providers and '
        'the add row; the override provider is checked', (tester) async {
      final registry = ProviderRegistry.inMemory();
      await registry.add(
        name: 'Acme',
        baseUrl: 'https://acme.example/v1',
        modelId: 'acme-1',
      );
      await _pumpWithOpener(
        tester,
        MediaSlotProviderPickerPage(
          slot: MediaSlot.imageGeneration,
          title: 'Edit Image generation',
          mainBaseUrl: 'https://openrouter.ai/api/v1',
          initial: const MediaSlotOverride(
            providerKind: 'openai-completions',
            baseUrl: 'https://acme.example/v1',
            modelId: 'acme-img',
          ),
          registry: registry,
          modelsFetcher: _someModels,
        ),
        (_) {},
      );
      await _open(tester);

      expect(find.text('Edit Image generation'), findsOneWidget);
      expect(find.text('Main connection'), findsOneWidget);
      expect(find.text('OpenRouter'), findsOneWidget);
      expect(find.text('Ollama'), findsOneWidget);
      expect(find.text('Acme'), findsOneWidget);
      // The AIIN row added one more entry — the trailing add row can sit
      // below the fold, so scroll it into view before asserting.
      await tester.scrollUntilVisible(
        find.text('Add provider'),
        120,
        scrollable: find.byType(Scrollable).last,
      );
      expect(find.text('Add provider'), findsOneWidget);
      expect(find.text('acme.example'), findsOneWidget);
      // Exactly one row is checked — the override's provider.
      expect(find.byIcon(Icons.check), findsOneWidget);
      final checkedTile = tester.widget<ListTile>(
        find.ancestor(
          of: find.byIcon(Icons.check),
          matching: find.byType(ListTile),
        ),
      );
      expect((checkedTile.title as Text).data, 'Acme');
    });

    testWidgets('connectedOnly hides hosted presets whose key does not '
        'resolve (the agent-role flow)', (tester) async {
      final registry = ProviderRegistry.inMemory();
      await registry.add(
        name: 'Acme',
        baseUrl: 'https://acme.example/v1',
        modelId: 'acme-1',
      );
      await _pumpWithOpener(
        tester,
        MediaSlotProviderPickerPage(
          slot: null, // the generic provider→model role flow
          title: 'Quick model',
          mainBaseUrl: 'https://openrouter.ai/api/v1',
          registry: registry,
          modelsFetcher: _someModels,
          connectedOnly: true,
        ),
        (_) {},
      );
      await _open(tester);

      // No keys configured in the test environment: hosted presets hide,
      // the main connection + saved custom providers stay.
      expect(find.text('Main connection'), findsOneWidget);
      expect(find.text('Acme'), findsOneWidget);
      expect(find.text('OpenRouter'), findsNothing);
      expect(find.text('Ollama'), findsNothing);
      expect(find.text('Add provider'), findsOneWidget);
    });

    testWidgets('a custom provider on a hosted preset endpoint dedupes it', (
      tester,
    ) async {
      final registry = ProviderRegistry.inMemory();
      await registry.add(
        name: 'My OpenRouter',
        baseUrl: 'https://openrouter.ai/api/v1',
        modelId: 'acme-1',
      );
      await _pumpWithOpener(
        tester,
        MediaSlotProviderPickerPage(
          slot: null,
          title: 'Quick model',
          registry: registry,
          modelsFetcher: _someModels,
        ),
        (_) {},
      );
      await _open(tester);

      // The hosted OpenRouter preset is covered by the saved instance.
      expect(find.text('My OpenRouter'), findsOneWidget);
      expect(find.text('OpenRouter'), findsNothing);
      expect(find.text('Ollama'), findsOneWidget);
    });

    testWidgets('connectedOnly: a preset with a host-scoped FA_KEY_<HOST> '
        'key still lists (CLI parity)', (tester) async {
      FaUiHost.keyResolver = (name) =>
          name == 'FA_KEY_OPENROUTER_AI' ? 'sk-or-scoped' : '';
      addTearDown(() => FaUiHost.keyResolver = null);
      await _pumpWithOpener(
        tester,
        const MediaSlotProviderPickerPage(
          slot: null,
          title: 'Quick model',
          connectedOnly: true,
        ),
        (_) {},
      );
      await _open(tester);

      expect(find.text('OpenRouter'), findsOneWidget);
      expect(find.text('Ollama'), findsNothing);
    });

    testWidgets('the main connection row pops a clear result', (tester) async {
      MediaSlotEditorResult? result;
      var popped = false;
      await _pumpWithOpener(
        tester,
        const MediaSlotProviderPickerPage(
          slot: MediaSlot.imageGeneration,
          title: 'Edit Image generation',
        ),
        (value) {
          popped = true;
          result = value;
        },
      );
      await _open(tester);

      await tester.tap(find.text('Main connection'));
      await tester.pumpAndSettle();

      expect(popped, isTrue);
      expect(result, isNotNull);
      expect(result!.cleared, isTrue);
      expect(result!.override, isNull);
    });

    testWidgets('add provider routes through the settings preset picker; '
        'the saved provider opens its model page', (tester) async {
      final registry = ProviderRegistry.inMemory();
      await _pumpWithOpener(
        tester,
        MediaSlotProviderPickerPage(
          slot: MediaSlot.imageGeneration,
          title: 'Edit Image generation',
          registry: registry,
          modelsFetcher: _someModels,
        ),
        (_) {},
      );
      await _open(tester);

      await tester.tap(find.text('Add provider'));
      await tester.pumpAndSettle();
      // Issue #975 (d54180f0): EVERY add-provider entry opens the ONE
      // settings flow — the preset picker, never the bare editor push.
      expect(find.byType(AddProviderPresetPickerPage), findsOneWidget);
      expect(find.byType(ProviderEditorPage), findsNothing);

      // The preset list is a lazy ListView — scroll the trailing Custom
      // tile into view before tapping it.
      await tester.scrollUntilVisible(
        find.text('Custom'),
