        ' pi $glyph Test Model $glyph yolo $glyph 23% $glyph \$0.00 ',
        'input',
      ];
      final faScreen = [
        'other banner',
        ' >_Fa $glyph test-model $glyph yolo $glyph 23% $glyph \$0.00 ',
