        'boot: segment 2 shape differs — '
            'fa <word:3> (test model extra), omp <word:2> (Test Model)',
        'boot: segment 4 shape differs — '
            'fa <time> (4m 30s), omp <pct> (23%)',
      ]);
    });
  });
