/// A `/models` fetch reporting image and vision models.
Future<ModelsEndpointInfo> _someModels(
  String baseUrl, {
  required String apiKey,
}) async => (
  const ['gpt-image-1', 'dall-e-3', 'gpt-4o'],
  const <String, int>{},
  const <String, int>{},
